import {renderJourneyPanel} from './journey-panels.js?v=0.6.0';
import {createFeedback} from './feedback.js?v=0.6.0';
import {worldObjects} from '../core/encounters.js?v=0.6.0';
import {installDisplay} from './display.js?v=0.5.2';
import {DUNGEONS,ELITES,AUGMENTS,forgeCost,salvageYield} from '../content/adventures.js?v=0.3.1';
import {questNavigation,trackedQuest,navigationGoal} from '../core/navigation.js?v=0.3.1';
import {ECHO_PRICE,TUNING,tuningRank,tuningCost,canTune,salePrice,questSoulReward,afterglow} from '../content/economy.js?v=0.3.1';
import {BUILDS,RARITIES,killXP,recommendedStat,SETS} from '../content/progression.js?v=0.3.1';import {QUESTS,DIALOGUES} from '../content/quests.js?v=0.3.1';import {questAvailable,questReady,objectiveProgress,questsForNPC} from '../core/quest-rules.js?v=0.3.1';
import {ATLAS} from '../content/atlas.js?v=0.3.1';
import {CLASSES,STAT_KEYS,EFFECTS,BRANCH_RULES,skillFor} from '../content/classes.js?v=0.3.1';import {ZONES,REGION,ITEM_TEMPLATES,ENEMIES} from '../content/region.js?v=0.3.1';
import {makeHero,derive,xpNeeded,compare,uid,lineOfSight} from '../core/rules.js?v=0.3.1';import {LocalSession,RemoteSession} from '../net/client.js?v=0.3.1';import {loadSave,getLegacy,migrateV1,saveLocal,validateImported} from '../core/storage.js?v=0.3.1';import {launchScene} from '../render/scene.js?v=0.3.1';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let session=null,selectedClass='swordsman',panel=null,lastHUD=0,toastTimer,logs=[],joystick={x:0,y:0},serverAvailable=false;let sceneHandle,inventoryTab="all",dialogueObject=null;
const hero=()=>session?.state.players[session.id];
const feedback=createFeedback();
let drawerOpen=false;try{drawerOpen=localStorage.getItem('vyriy-quest-drawer')==='open'}catch{}
function setQuestDrawer(value){drawerOpen=value;$('quest-hud').classList.toggle('is-collapsed',!value);$('quest-drawer-toggle').setAttribute('aria-expanded',String(value));$('quest-drawer-toggle').setAttribute('aria-label',value?'Згорнути журнал':'Розгорнути журнал');$('quest-drawer-body').inert=!value;try{localStorage.setItem('vyriy-quest-drawer',value?'open':'closed')}catch{}}
setQuestDrawer(drawerOpen);
installDisplay({root:document.documentElement,button:$('fullscreen-toggle'),toast,fallback:()=>{panel='screen';show('Горизонтальна гра на весь екран',`<p class="notice">Цей браузер не дозволив увімкнути повний екран кнопкою. Гра також працює при звичайному повороті телефона.</p><p>Поверніть телефон горизонтально. Якщо екран не повертається, вимкніть блокування орієнтації в налаштуваннях телефона.</p><h3>iPhone / iPad · без адресного рядка</h3><p>У Safari відкрийте «Поділитися» → «На початковий екран». Залиште «Відкривати як вебпрограму» увімкненим, якщо цей перемикач доступний. Запускайте Вирій із доданої іконки, потім поверніть телефон.</p><h3>Android</h3><p>Відкрийте гру у Chrome та натисніть ⛶ Екран. Також можна додати гру на початковий екран через меню браузера.</p><p class="small muted">Браузер може зберігати прогрес вебпрограми окремо. Перед першим запуском з іконки експортуйте збереження через меню гри; за потреби імпортуйте його у вебпрограмі.</p><button class="btn" data-close>Продовжити гру</button>`);}});


function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200)}
function command(type,data={}){if(!session)return;let r=session.command(type,data);if(r.error)toast(r.error);return r;}
function artStyle(classId,col=0){let row=CLASSES[classId].atlas,sheet=row>3?'heroes-extra-v2.png':'heroes-v2.png';let meta=ATLAS[row>3?'extra':'heroes'];if(row>3)row-=4;let x=meta.cols[col],y=meta.rows[row],w=meta.cols[col+1]-x,ht=meta.rows[row+1]-y;return`background-image:url(assets/${sheet});background-size:${meta.width/w*100}% ${meta.height/ht*100}%;background-position:${x/(meta.width-w)*100}% ${y/(meta.height-ht)*100}%`}
function show(title,html,kicker='ХРОНІКИ ОБЕРЕГУ'){ $('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal-kicker').textContent=kicker;if(!$('modal').open)$('modal').showModal();$('modal').classList.toggle('creating',panel==='create');$('modal').classList.toggle('skill-panel',panel==='spec');}
function close(){$('modal').close();panel=null;}
function choose(){panel='create';let c=CLASSES[selectedClass],saved=loadSave(),legacy=getLegacy();show('Оберіть свою історію',`<p class="muted">Один персонаж. Ваш клас, ваш шлях. Пригода починається у Вербовій слободі.</p><div class="class-grid">${Object.entries(CLASSES).map(([id,c])=>`<button class="class-card ${id===selectedClass?'selected':''}" data-class="${id}" aria-pressed="${id===selectedClass}"><span class="preview-art" style="${artStyle(id)}"></span><b>${c.name}</b><small>${c.role}</small></button>`).join('')}</div><div class="creation-summary"><div><p><b>${c.name}</b> · ${c.role}</p><p class="muted">${c.skills.map(s=>s.icon+' '+s.name).join(' · ')}</p><p class="small">Спеціалізації: 20 / 40 / 60 · фінальна форма: 85</p></div><div><label for="character-name">Ім’я персонажа</label><div class="field"><input id="character-name" maxlength="22" value="${escape(sessionStorage.getItem('vyriy-name')||'Мандрівник')}" aria-label="Ім’я персонажа"></div></div></div>${legacy&&!saved?'<label class="checkline"><input id="migrate-legacy" type="checkbox" checked> Перенести прогрес першої версії. Старе збереження залишиться.</label>':''}<button id="start-local" class="btn">Почати локальну пригоду →</button>${saved?'<button id="continue-local" class="btn secondary">Продовжити збережену гру</button>':''}<button id="start-coop-menu" class="btn secondary">Кооператив · до 8 гравців</button><p class="small muted">Локальний режим не є MMO. У мережевому режимі один гравець контролює лише свого персонажа; сервер обчислює бій, нагороди та спільні переходи.</p>`,'В И Р І Й · ВЕРБОВЕ ПРИКОРДОННЯ');}
function startLocal(continuing=false){let saved=continuing?loadSave():null;if(saved){for(let p of Object.values(saved.players)){p.online=true;p.path=[];p.auto=false;}session=new LocalSession(saved);close();return;}let name=$('character-name')?.value.trim()||sessionStorage.getItem('vyriy-name')||'Мандрівник';if(!/^[\p{L}\p{N} ’'-]{1,22}$/u.test(name)){toast('Ім’я: 1–22 літери або цифри');return}sessionStorage.setItem('vyriy-name',name);let h=$('migrate-legacy')?.checked?migrateV1(getLegacy(),selectedClass,name):makeHero(selectedClass,name);session=new LocalSession(null,h);session.save();close();toast('WASD або дотик — рух. Поговоріть із Берегинею.');}
function nearestObject(){let h=hero();if(!h)return null;return worldObjects(session.state).filter(o=>Math.hypot(h.x-o.x-.5,h.y-o.y-.5)<2.8&&lineOfSight(session.state.zone,h,{x:o.x+.5,y:o.y+.5},session.state.flags)).sort((a,b)=>Math.hypot(h.x-a.x-.5,h.y-a.y-.5)-Math.hypot(h.x-b.x-.5,h.y-b.y-.5))[0];}
function interact(o){if(!o)return toast('Поруч немає об’єкта. Підійдіть до NPC, скрині або входу.');let r=command('interact',{id:o.id});if(r?.error)return;if(o.kind==='storage')open('storage');else if(o.kind==='journey')open('journey');else if(o.kind==='forge')open('forge');else if(o.kind==='merchant')open('shop');else if(o.kind==='camp'&&DUNGEONS[session.state.zone])open('dungeon');else if(o.kind==='npc'){showDialogue(o);}}
function action(id){if(!session)return;if(id==='attack')command('attack');if(id==='skill0'||id==='skill1')command('skill',{index:id==='skill0'?0:1});if(id==='potion'){let item=hero().inventory.find(i=>i.template==='potion');if(item)command('use',{id:item.id});else toast('Червоні зілля закінчилися')}if(id==='interact')interact(nearestObject());}
function objectiveLabel(o){return o.label||ITEM_TEMPLATES[o.id]?.name||ENEMIES[o.id]?.name||Object.values(ZONES).flatMap(z=>z.objects).find(x=>x.id===o.id)?.name||({seals:'Печатки лісу',ending:'Серце Оберегу',marshLight:'Болотяна святиня',abbeyBell:'Дзвін собору',forgeFlame:'Перше горно',worldLight:'Останній маяк'})[o.id]||o.id}
function questCards(list,npc=false){let h=hero(),s=session.state;return list.map(q=>`<article class="card"><span class="tag">Рів. ${q.level} · ${h.quests[q.id]?.status==='completed'?'Завершено':h.quests[q.id]?.status==='active'?'У журналі':'Нове'}</span><h3>${escape(q.title)}</h3><p>${escape(q.text)}</p><p>${q.objectives.map(o=>`${escape(objectiveLabel(o))}: ${objectiveProgress(h,s,o)} / ${o.count}`).join('<br>')}</p><p>Нагорода: ${q.reward.xp} XP · ${q.reward.zeny} Z · ✧ ${questSoulReward(q)} відлунь</p>${q.reward.item==='classLegendary'?`<p class="legendary-reward">✦ ${escape(ITEM_TEMPLATES['legendary-'+h.classId+'-40'].name)} · Легендарна зброя · рів. 40<br>${Object.entries(ITEM_TEMPLATES['legendary-'+h.classId+'-40'].stats).map(([k,v])=>`${escape(k.toUpperCase())} +${k==='haste'?Math.round(v*100)+'%':v}`).join(' · ')}<br>Особиста нагорода для класу «${escape(CLASSES[h.classId].name)}»</p>`:''}${h.quests[q.id]?.status!=='completed'?`<button class="btn secondary" data-quest-track="${q.id}">${h.trackedQuest===q.id?'⌖ Обрано для навігації':'⌖ Показати шлях'}</button>`:''}${npc&&questAvailable(h,q)?`<button class="btn" data-quest-accept="${q.id}">Взяти завдання</button>`:npc&&h.quests[q.id]?.status==='active'?`<button class="btn" data-quest-claim="${q.id}" ${questReady(h,s,q)?'':'disabled'}>Отримати нагороду</button>`:''}</article>`).join('')}
function showDialogue(o,answer=''){dialogueObject=o;panel='dialogue';show(o.name,`<p class="dialogue">«${escape(answer||o.dialogue)}»</p>${(DIALOGUES[o.id]||[]).map((d,i)=>`<button class="btn secondary" data-dialogue="${i}">${escape(d.prompt)}</button>`).join('')}<div class="card-grid">${questCards(questsForNPC(hero(),o.id),true)}</div><button class="btn secondary" data-close>Вирушаю →</button>`)}
function tuningCards(h,a){return `<div class="soul-tuning"><h4>✧ Підсилення відлуннями</h4><p>Оберіть один напрям. Перший вибір — 2 відлуння, зміна — 3. Від рівня 10, біля привалу або кузні.</p>${Object.entries(AUGMENTS).map(([key,t])=>`<div class="soul-option"><b>${t.name}${h.skillAugments?.[a.id]===key?' ✓':''}</b><p>${t.desc}</p><button class="btn secondary" data-skill-augment="${a.id}" data-choice="${key}" ${h.skillAugments?.[a.id]===key||h.level<10||!h.skillRanks[a.id]||h.echoes<(h.skillAugments?.[a.id]?3:2)?'disabled':''}>${h.skillAugments?.[a.id]===key?'Обрано':'Обрати · '+(h.skillAugments?.[a.id]?3:2)+' відлуння'}</button></div>`).join('')}${Object.entries(TUNING).filter(([key])=>canTune(a,key)).map(([key,t])=>{let rank=tuningRank(h,a.id,key),cost=tuningCost(h,a.id,key),glow=key==='afterglow'?afterglow({...h,skillTuning:{...h.skillTuning,[a.id]:{...h.skillTuning?.[a.id],afterglow:Math.max(1,rank)}}},a.id):null;return `<div class="soul-option"><b>${t.name} · ${rank}/5</b><p>${key==='crit'?`Зараз +${rank*2} в.п. до критичного шансу цієї навички.`:glow?`${EFFECTS[glow.id].name} · ${glow.duration.toFixed(1)} с${glow.potency?' · сила '+Math.round(glow.potency):''}${rank?'':' · перший ранг'}`:''}<br>${t.desc}</p><button class="btn secondary" data-skill-tune="${a.id}" data-tune-key="${key}" ${cost===null||h.echoes<cost||h.level<10+rank*5||!h.skillRanks[a.id]?'disabled':''}>${cost===null?'Максимум':`Підсилити · ${cost} відлунь`}</button>${cost!==null?`<small>Потрібен рівень ${10+rank*5}</small>`:''}</div>`}).join('')}</div>`;}
function itemCards(items,shop=false){let h=hero();let grouped=[];for(let item of items){let t=ITEM_TEMPLATES[item.template],stack=!shop&&['consumable','material','quest','card'].includes(t.kind)&&grouped.find(g=>g.template===item.template);if(stack)stack.count++;else grouped.push({...item,count:1})}return grouped.map(item=>{let t=ITEM_TEMPLATES[item.template],equipped=Object.values(h.equipment).includes(item.id),delta=['weapon','armor','accessory'].includes(t.kind)?compare(h,item.id):null;let changes=delta?Object.entries(delta).filter(([k,v])=>Math.abs(v)>.01).map(([k,v])=>`<span class="${v<0?'negative':''}">${k.toUpperCase()} ${v>0?'+':''}${v.toFixed(k==='interval'?2:0)}${k==='interval'?' с':''}</span>`).join(' · '):'';return`<article class="card" style="border-color:${RARITIES[item.rarity||t.rarity||'common'].color}"><span class="tag">${RARITIES[item.rarity||t.rarity||'common'].name}</span><span class="icon">${t.icon||'◆'}</span> ${equipped?'<span class="tag">Споряджено</span>':''}<h3>${t.name}${item.count>1?' ×'+item.count:''}${item.quality?' +'+item.quality:''}</h3><p>${t.desc||'Матеріал для торгівлі.'}</p><p>Вимоги: рів. ${t.requirements.level}${t.requirements.classes?' · '+t.requirements.classes.map(c=>CLASSES[c].name).join(', '):''}<br>${Object.entries(t.stats).map(([k,v])=>k.toUpperCase()+' +'+v).join(' · ')}${item.card?' · руна +3 ATK/MATK':''}${t.set?'<br>Комплект: '+SETS[t.set].name+' · 2/3 предмети: '+Object.entries(SETS[t.set].bonuses).map(([n,b])=>n+' частини: '+Object.entries(b).map(([k,v])=>k.toUpperCase()+' +'+v).join(', ')).join('; '):''}</p>${changes?`<p class="comparison">Зміна при заміні: ${changes}</p>`:''}<details><summary>Дані предмета${item.count>1?' · перший у групі':''}</summary><small class="item-id">ID ${escape(item.id)}<br>Власник: ${escape(h.name)}</small></details><div>${shop?`<button class="btn" data-buy="${item.template}">Купити · ${Math.ceil(t.price*(h.classId==='merchant'?.9:1))} Z</button>`:t.kind==='consumable'?`<button class="btn" data-use="${escape(item.id)}">Використати</button>`:['weapon','armor','accessory'].includes(t.kind)?`<button class="btn" data-equip="${escape(item.id)}" ${equipped?'disabled':''}>Спорядити</button>`:t.kind==='card'?`<button class="btn" data-socket="${escape(item.id)}">У зброю</button>`:''}${!shop&&!equipped&&salePrice(t,item)>0?`<button class="btn secondary" data-sell="${escape(item.id)}">Продати${item.count>1?' 1':''} · ${salePrice(t,item)} Z</button>${item.count>1?`<button class="btn secondary" data-sell="${escape(item.id)}" data-sell-count="${item.count}">Продати ×${item.count} · ${salePrice(t,item)*item.count} Z</button>`:''}`:''}${session.mode==='online'&&!equipped&&t.kind!=='quest'&&!t.bound?`<button class="btn secondary" data-offer="${escape(item.id)}">Передати…</button>`:''}</div></article>`}).join('');}
function open(name){panel=name;let h=hero(),s=session?.state;if(name==='create'){choose();return;}if(name==='coop'&&!h){showCoop();return;}if(!h)return;let d=derive(h),title='',html='';const extra=renderJourneyPanel(name,h,s);if(extra){show(extra.title,extra.html);return;}switch(name){case'forge':title='Зоряна кузня';html=`<p class="notice">${h.zeny} Z · жар-уламки: ${h.inventory.filter(i=>i.template==='embershard').length}. Зніміть річ перед роботою. Кожне +1 додає 12% базових показників речі; максимум +5. Успіх гарантований. Особисті нагороди гартуються, але не розбираються.</p><div class="card-grid">${h.inventory.filter(i=>['weapon','armor','accessory'].includes(ITEM_TEMPLATES[i.template].kind)).map(i=>{let t=ITEM_TEMPLATES[i.template],cost=forgeCost(i),equipped=Object.values(h.equipment).includes(i.id);return `<article class="card"><h3>${t.name} +${i.quality||0}</h3>${equipped?`<p>Споряджено</p><button class="btn secondary" data-unequip="${i.id}">Зняти для роботи</button>`:`<button class="btn" data-forge="${i.id}" ${(i.quality||0)>=5?'disabled':''}>${(i.quality||0)>=5?'Максимум +5':`Гартувати · ${cost.shards} уламків + ${cost.zeny} Z`}</button>${!t.bound?`<details><summary>Розібрати предмет</summary><p>Предмет зникне назавжди. Отримаєте ${salvageYield(i)} жар-уламків.</p><button class="btn secondary" data-salvage="${i.id}">Підтвердити розбір</button></details>`:'<p>Особиста нагорода захищена від розбору</p>'}`}</article>`}).join('')}</div>`;break;
case'hero':title=h.name+' · '+CLASSES[h.classId].name;html=`<div class="notice">Рівень ${h.level} / 85 · досвід ${h.xp} / ${xpNeeded(h.level)} · вільні очки: ${h.statPoints}<br>За кожен новий рівень — 5 очок. Спеціалізації на 20, 40, 60 та фінальна форма на 85.</div><div class="notice"><b>Рекомендовано: ${BUILDS[h.classId].name}</b><p>${BUILDS[h.classId].reason}</p><p>${Object.entries(BUILDS[h.classId].weights).map(([k,v])=>k+' · '+v).join(' / ')} · наступна характеристика: ${recommendedStat(h)||'межу досягнуто'}</p><button class="btn" data-recommend="yes" ${h.statPoints?'':'disabled'}>Розподілити до 5 очок за порадою</button></div><div class="stat-grid">${STAT_KEYS.map(k=>`<div class="stat-row"><span>${k}</span><b>${h.stats[k]}</b><button data-stat="${k}" ${h.statPoints<1||h.stats[k]>=99?'disabled':''} aria-label="Підвищити ${k}">+</button></div>`).join('')}</div><h3 class="section-title">Поточні бойові показники</h3><div class="card-grid">${[['HP',d.hp],['SP',d.sp],['ATK',d.atk],['MATK',d.matk],['DEF',d.def],['MDEF',d.mdef],['HIT',d.hit],['FLEE',d.flee],['Критичний шанс',(d.crit*100).toFixed(1)+'%'],['Інтервал атак',d.interval.toFixed(2)+' с']].map(([k,v])=>`<div class="card"><b>${k}</b><p>${typeof v==='number'?v.toFixed(1):v}</p></div>`).join('')}</div><p class="small muted">Це робочі формули поточної версії. Баланс підлягає перевірці грою.</p>`;break;
case'inventory':title='Торба мандрівника';html=`<div class="panel-tools"><button class="btn secondary" data-sort-inventory="yes">Сортувати торбу</button><button class="btn secondary" data-open="relics">Класові реліквії</button><button class="btn secondary" data-open="rewards">Нагороди · ${h.dungeonRewards?.length||0}</button></div><p class="notice">${h.inventory.length} предметів · ${h.zeny} Z · ✧ ${h.echoes||0} Відлуння душ. Продаж прямо з торби; квестові й особисті нагороди захищені. Порівняння враховує активні бонуси комплекту.</p><nav class="inventory-tabs">${[['all','Усе'],['consumable','Зілля'],['armor','Спорядження'],['weapon','Зброя'],['quest','Квестові'],['material','Матеріали й карти']].map(([id,label])=>`<button class="btn ${inventoryTab===id?'':'secondary'}" data-inventory-tab="${id}" aria-pressed="${inventoryTab===id}">${label}</button>`).join('')}</nav><div class="card-grid">${itemCards(h.inventory.filter(i=>{let k=ITEM_TEMPLATES[i.template].kind;return inventoryTab==='all'||inventoryTab==='armor'&&['armor','accessory'].includes(k)||inventoryTab==='material'&&['material','card'].includes(k)||k===inventoryTab}))||'<p>У цій вкладці порожньо.</p>'}</div>`;break;
case'shop':title='Крамниця та обмін відлунь';html=`<p class="notice">Гаманець: ${h.zeny} Z · ✧ ${h.echoes||0} відлунь. Купувати можна лише біля торговця. Коваль має знижку 10% на товари.</p><article class="card"><h3>✧ Відлуння душ · ${h.echoes||0}</h3><p>1 відлуння = ${ECHO_PRICE} Z. Використовуються для окремого підсилення кожної навички.</p>${[1,5,10].map(n=>`<button class="btn" data-buy-echoes="${n}" ${h.zeny<n*ECHO_PRICE?'disabled':''}>Купити ${n} · ${n*ECHO_PRICE} Z</button>`).join('')}</article><div class="card-grid">${itemCards(['potion','ether',CLASSES[h.classId].weapon,'armor',...Object.keys(ITEM_TEMPLATES).filter(id=>ITEM_TEMPLATES[id].shop&&ITEM_TEMPLATES[id].requirements.classes?.includes(h.classId))].map(template=>({template,id:'Крамниця',owner:h.id})),true)}</div><h3 class="section-title">Продати зайве</h3><div class="card-grid">${itemCards(h.inventory.filter(i=>salePrice(ITEM_TEMPLATES[i.template],i)>0&&!Object.values(h.equipment).includes(i.id)))||'<p class="empty">Матеріалів ще немає.</p>'}</div>`;break;
case'spec':title='Ваш професійний шлях';let c=CLASSES[h.classId];html=`<button class="btn secondary" data-open="relics">Реліквії: зміна поведінки навичок</button><p class="notice">✧ Відлуння душ: ${h.echoes||0}. Рідкісний дроп із відповідних рівню ворогів, гарантована нагорода босів і квестів. У торговців: ${ECHO_PRICE} Z за 1. Критичний шанс й післясвітіння покращуються для кожної навички окремо.</p><p class="notice">${c.name} · ${c.role}<br>Навички витрачають SP та мають окреме відновлення. Нові спеціалізації змінюють поведінку прийомів.</p><div class="card-grid">${c.skills.map(a=>{let rank=h.skillRanks[a.id]||0,sk=skillFor(h,a.id)||a;return `<div class="card"><span class="icon">${a.icon}</span><h3>${a.name} · ${rank}/5</h3><p>Від рівня ${a.unlock} · ${sk.cost} SP · ${sk.cd} с<br>${a.effect?EFFECTS[a.effect].rule:'Активний прийом із видимою анімацією.'}</p><button class="btn" data-skill-upgrade="${a.id}" ${rank>=5||h.skillPoints<1||h.level<a.unlock+rank*2?'disabled':''}>${rank?'Покращити':'Вивчити'} · 1 очко</button>${tuningCards(h,a)}${rank?[0,1].map(slot=>`<button class="btn secondary" data-skill-assign="${a.id}" data-slot="${slot}" ${h.skillbar[slot]===a.id?'disabled':''}>${h.skillbar[slot]===a.id?'✓ ':''}Комірка ${slot+1}</button>`).join(''):''}</div>`}).join('')}</div><p class="notice">Очки навичок: ${h.skillPoints}. Кожен новий рівень дає 1 очко; наступний ранг потребує ще 2 рівні персонажа. Відновлення належить навичці й не скидається при заміні.</p>${[20,40,60,85].map((level,idx)=>`<h3 class="section-title">${level===85?'Фінальна форма':'Спеціалізація'} · ${level} рівень</h3><div class="card-grid">${BRANCH_RULES[level].map((r,i)=>`<div class="card"><span class="tag">${h.level<level?'Недоступно':h.specs[level]===i?'Обрано ✓':'Доступно'}</span><h3>${level===85?c.final:c.branches[idx][i]}</h3><p>${r.desc}</p><button class="btn" data-spec="${level}" data-index="${i}" ${h.level<level||h.specs[level]!==undefined?'disabled':''}>Обрати шлях</button></div>`).join('')}</div>`).join('')}`;break;
case'map':title='Шляхи Вирію';html=`<button class="btn secondary" data-open="dungeon">Експедиція в поточній локації</button><p class="notice">Переходи — біля входів у світі. У кооперативі маршрут обирається голосуванням.</p><div class="map-layout">${Object.values(ZONES).map(z=>`<div class="map-zone ${s.zone===z.id?'current':''}"><h3>${z.name}</h3><p>${DUNGEONS[z.id]?'✦ Повторний данж<br>':''}Рекомендовані рівні: ${(z.levels||[1,15]).join('–')}<br>${z.objects.filter(o=>['portal','door'].includes(o.kind)).map(o=>'→ '+ZONES[o.to]?.name+(o.requires&&!s.flags[o.requires]?' · потрібна сюжетна подія':'')+(o.minLevel>1?' · від рів. '+o.minLevel:'')+(o.requiresQuest&&h.quests[o.requiresQuest]?.status!=='completed'?' · завершити «Зоряне горно»':'')).join('<br>')}</p></div>`).join('')}</div>`;break;
case'quest':title='Хроніки Оберегу';html=`<div class="notice">✦ Спадщина семи шляхів · ${QUESTS.filter(q=>q.id.startsWith('legacy-')&&h.quests[q.id]?.status==='completed').length}/8<br>Початок: Садівниця Весна, Долина першого цвіту, рів. 10.<br>Фінал: Зоряний коваль Тарас, підземелля Багряного замку II, рів. 40. Нагорода: легендарна зброя твого класу.</div><p class="dialogue">Від росистих лук до останнього вогню на крижаному перевалі. Беріть і здавайте завдання особисто в їхніх оповідачів.</p><div class="card-grid">${questCards(QUESTS.filter(q=>h.quests[q.id]||questAvailable(h,q)))}</div><h3>Майбутні історії</h3><p>${QUESTS.filter(q=>!h.quests[q.id]&&!questAvailable(h,q)).map(q=>`${q.title} · рів. ${q.level}`).join('<br>')}</p>`;break;
case'effects':title='Стани та ефекти';html=`<p class="notice">Ефекти спрацьовують у симуляції. Після закінчення таймера модифікатор зникає; отрута не має зайвого тіку після завершення.</p><div class="effect-list">${Object.entries(EFFECTS).map(([id,e])=>`<div class="card"><b style="color:${e.color}">${e.icon} ${e.name}</b><p>Типово ${e.duration} с · максимум ${e.maxStacks} ${e.maxStacks===1?'заряд':'заряди'}</p><p>${e.rule}</p></div>`).join('')}</div>`;break;
case'help':title='Порадник мандрівника';html=`<div class="card-grid"><div class="card"><h3>Екран і рух</h3><p>⛶ Екран угорі: повний екран та горизонтальний режим, якщо браузер підтримує. На iPhone доступний запуск з іконки початкового екрана.</p><p>ПК: WASD / стрілки або клік по землі. Пробіл — атака, 1/2 — навички, 3 — зілля, E — взаємодія.<br>Телефон: джойстик праворуч; велика атака ліворуч, навички дугою над нею. Також можна торкнутися землі. Наведення не потрібне.</p></div><div class="card"><h3>Бій</h3><p>Торкніться видимого ворога, щоб наблизитися й почати звичайні атаки. Рух перериває переслідування. Навички активуйте окремо. Снаряди мають час польоту; червоні зони боса потрібно залишати.</p></div><div class="card"><h3>Взаємодія</h3><p>Підійдіть до об’єкта і натисніть «Взаємодія». Поговоріть із Орисею, візьміть стартову скриню. Торговець продає спорядження й купує матеріали. Вогнище відновлює HP/SP, коли ворогів поблизу немає.</p></div><div class="card"><h3>Кооператив</h3><p>Серверна кімната — до 8 гравців. Позначте готовність перед важливою подією. Голосування показує предмет рішення; при рівності вирішує голос лідера. Передача предмета потребує прийняття одержувачем поруч.</p></div></div><button class="btn secondary" data-open="effects">Усі стани й правила →</button><button class="btn secondary" data-open="bestiary">Бестіарій →</button>`;break;
case'bestiary':title='Істоти прикордоння';html=`<div class="card-grid">${Object.entries(ENEMIES).map(([id,e])=>`<article class="card"><span class="tag">${e.boss?'БОС':'Рів. '+e.level}</span><h3>${e.name}</h3><p>${e.aggression==='passive'?'Мирний · відповідає на напад':'Агресивний · атакує першим'}<br>${e.role}<br>Базові показники сімейства · HP ${e.hp} · ATK ${e.atk} · DEF ${e.def} · MDEF ${e.mdef}<br>Дальність ${e.range} · період ${e.period} с</p></article>`).join('')}</div>`;break;
case'coop':showCoop();return;
case'menu':title='Налаштування пригоди';html=`<h3>Відчуття бою</h3><div class="panel-tools">${[['sound','Звук'],['haptics','Вібрація'],['motion','Ефекти ударів']].map(([key,label])=>`<button class="btn secondary" data-feedback="${key}" aria-pressed="${feedback.prefs[key]}" ${key==='haptics'&&!navigator.vibrate?'disabled':''}>${label}: ${feedback.prefs[key]?'увімкнено':'вимкнено'}${key==='haptics'&&!navigator.vibrate?' · недоступна':''}</button>`).join('')}</div><p class="notice">${session.mode==='local'?'Локальний режим: збереження версії 3 на цьому пристрої. Старе збереження v1 не видаляється.':'Мережевий режим: стан та інвентар зберігає авторитетний сервер. Локальний JSON не імпортується в мережеву економіку.'}</p><button class="btn" id="export-save" ${session.mode==='online'?'disabled':''}>Експортувати збереження</button><label class="btn secondary" ${session.mode==='online'?'hidden':''}>Імпортувати<input id="import-save" type="file" accept="application/json" hidden></label><button class="btn secondary" id="character-menu">Екран персонажа</button><p class="small muted">Нова гра замінить лише поточне локальне збереження v2 після вибору класу. Перед цим можна експортувати прогрес.</p><button class="btn secondary" data-open="help">Керування й поради</button><p class="small muted">Версія 0.6.0 · Phaser 3.90 · 18 з’єднаних зон, 56 квестів, сезонні землі й багаторівневі замки. Локальна гра не є MMO. Розгорнутий статичний сайт не містить сервера кімнат.</p>`;break;
}show(title,html);}
function showCoop(){panel='coop';let h=hero(),online=session?.mode==='online',s=session?.state;if(online){show('Ваша кооперативна кімната',`<div class="notice">Авторитетний сервер · ${session.connected?'підключено':'перепідключення…'} · подія #${s.eventSeq} · раунд ${s.round}<br>Код кімнати: <b class="coop-code">${session.room}</b></div><p class="small muted">Інший гравець відкриває цей самий клієнт, обирає клас і вводить цей код та адресу сервера. Сесія прив’язана до вкладки; її можна відновити після розриву.</p><div class="card-grid">${Object.values(s.players).map(p=>`<div class="card"><h3>${escape(p.name)} ${p.id===s.leader?'♛':''}</h3><p>${CLASSES[p.classId].name} · ${p.online?'у мережі':'від’єднано'} · ${p.ready?'готовий ✓':'не готовий'}</p></div>`).join('')}</div><button class="btn" id="ready-toggle">${h.ready?'Скасувати готовність':'Я готовий'}</button><h3 class="section-title">Передачі предметів</h3>${s.offers.filter(o=>o.status==='pending').map(o=>`<div class="trade-row"><span>${escape(o.name)}<br><small>${escape(s.players[o.from]?.name)} → ${escape(s.players[o.to]?.name)}</small></span>${o.to===h.id?`<button class="btn" data-accept="${escape(o.id)}">Прийняти</button>`:'<span class="tag">Очікування · до 30 с</span>'}</div>`).join('')||'<p class="muted">Немає активних пропозицій. Відкрийте торбу, щоб передати власний неспоряджений предмет.</p>'}`);return;}
show('Кооператив · до 8 гравців',`<p class="notice">${serverAvailable?'Сервер доступний на поточній адресі.':'У цій публікації працює локальна гра. Для справжнього кооперативу потрібен запущений сервер із репозиторію: npm install → npm start. Можна вказати адресу доступного сервера нижче.'}</p><p class="small muted">Кімната має спільних ворогів і переходи, персональний лут та підтверджувану передачу речей. Сервер обчислює шкоду, дистанції та нагороди. Прогрес соло не переноситься в мережеву економіку.</p><div class="field"><label>Ваше ім’я<br><input id="coop-name" value="${escape(h?.name||sessionStorage.getItem('vyriy-name')||'Мандрівник')}" maxlength="22"></label><label>Клас<br><select id="coop-class">${Object.entries(CLASSES).map(([id,c])=>`<option value="${id}" ${id===(h?.classId||selectedClass)?'selected':''}>${c.name}</option>`).join('')}</select></label></div><div class="field"><label>Адреса сервера<br><input id="server-url" type="url" value="${escape(location.origin)}" placeholder="https://your-server.example"></label><label>Код кімнати (порожній — нова)<br><input id="room-code" maxlength="8" autocomplete="off" placeholder="a1b2c3d4"></label></div><button class="btn" id="connect-server">Увійти в кімнату</button><button class="btn secondary" id="back-local">${h?'Повернутися до гри':'Вибір персонажа'}</button><p class="small muted">Для доступу з іншого пристрою сервер повинен мати HTTPS/WSS та дозволений Origin. Платний хостинг не підключено.</p>`);}
function refreshPanel(){if(panel==='dialogue'){setTimeout(()=>showDialogue(dialogueObject),session?.mode==='online'?220:0);return}if(['hero','inventory','shop','spec','coop','quest','forge','dungeon','storage','rewards','relics','journey','menu'].includes(panel))setTimeout(()=>open(panel),session?.mode==='online'?220:0);}
function updateHUD(s,id,time){if(time-lastHUD<130)return;lastHUD=time;let h=s.players[id];if(!h)return;let d=derive(h),c=CLASSES[h.classId];if(session.mode==='online')$('save-status').textContent='Стан зберігає сервер · подія #'+s.eventSeq;$('hero-name').textContent=h.name;$('hero-level').textContent='РІВ. '+h.level;$('hero-art').setAttribute('style',artStyle(h.classId));$('hp-value').textContent=Math.ceil(h.hp)+' / '+Math.ceil(d.hp);$('hp-fill').style.width=Math.max(0,h.hp/d.hp*100)+'%';$('sp-value').textContent=Math.floor(h.sp)+' / '+Math.ceil(d.sp);$('sp-fill').style.width=h.sp/d.sp*100+'%';$('xp-fill').style.width=h.xp/xpNeeded(h.level)*100+'%';$('location-name').textContent=ZONES[s.zone].name;$('mode-label').textContent=session.mode==='local'?'Локальний режим · один герой':`Кімната ${session.room} · ${session.connected?'підключено':'перепідключення…'}`;$('quest-heading').textContent=s.flags.ending?'Оберіг знову сяє':s.flags.seals.length<3?'Три втрачені печатки':s.flags.boss?'Серце Оберегу':'Під старим храмом';$('quest-objective').textContent=s.flags.ending?'Розділ завершено. Прикордоння врятовано.':s.flags.seals.length<3?`Печатки лісу: ${s.flags.seals.length} / 3`:s.flags.boss?'Торкніться вівтаря в катакомбах':!s.flags.switch?'Відкрийте катакомби та знайдіть важіль':'Розбийте захисну печатку. Здолайте Хранителя.';let active=trackedQuest(h);if(active){$('quest-heading').textContent=active.title;$('quest-objective').textContent=active.objectives.map(o=>objectiveLabel(o)+': '+objectiveProgress(h,s,o)+'/'+o.count).join(' · ');let nav=questNavigation(h,s);if(nav)$('quest-objective').textContent+=(nav.ready?' · Умови виконані':'')+' · '+nav.label+(nav.reason?' · '+nav.reason:'');}else if(s.flags.ending){$('quest-heading').textContent='Шлях за межі прикордоння';$('quest-objective').textContent=s.flags.worldLight?'Останній маяк запалено.':'Поговоріть із Соломією на болотах · від рівня 14'}const goal=navigationGoal(h,s);if(goal?.activity){$('quest-heading').textContent=s.dungeonRun?.status==='active'?'Експедиція':'Подія на стежці';$('quest-objective').textContent=goal.label;}$('navigation-mode').hidden=!(s.dungeonRun?.status==='active'||s.travelEvent?.status==='active');for(let b of document.querySelectorAll('[data-navigation-mode]'))b.setAttribute('aria-pressed',String((h.navigationMode||'quest')===b.dataset.navigationMode));if(s.dungeonRun?.status==='active')$('quest-objective').textContent+=' · Данж: вартові '+s.dungeonRun.guards.filter(id=>s.enemies.some(e=>e.id===id&&e.dead)).length+'/3 → бос';if(s.travelEvent?.status==='active')$('quest-objective').textContent+=' · Подія: '+Math.max(0,Math.ceil(s.travelEvent.expires-s.clock))+' с';const mechanic=s.enemies.find(e=>e.boss&&!e.dead&&e.mechanicHint&&Math.hypot(e.x-h.x,e.y-h.y)<20);$('mechanic-hud').hidden=!mechanic;if(mechanic)$('mechanic-hud').textContent=mechanic.mechanicHint+(mechanic.ritual?' · '+Math.ceil(mechanic.ritual.left)+' с':'');$('party-hud').innerHTML=Object.values(s.players).filter(p=>p.id!==id).map(p=>`<div class="party-member"><span>${p.id===s.leader?'♛ ':''}${escape(p.name)}</span><span>${p.online?Math.ceil(p.hp)+' HP':'Від’єднано'}</span></div>`).join('');for(let i=0;i<2;i++){let b=$('skill'+i),sk=skillFor(h,h.skillbar[i]);b.querySelector('b').textContent=sk.icon;b.querySelector('span').textContent=sk.name;b.querySelector('em').textContent=h.cooldowns[sk.id]>0?Math.ceil(h.cooldowns[sk.id]):'';b.setAttribute('aria-label',sk.name+' · '+sk.cost+' SP');}let potions=h.inventory.filter(i=>i.template==='potion').length;$('potion').querySelector('span').textContent='Зілля ×'+potions;$('potion').querySelector('em').textContent=h.cooldowns.potion>0?Math.ceil(h.cooldowns.potion):'';$('bag-count').textContent=h.inventory.length;$('attack').classList.toggle('selected',h.auto);let near=nearestObject();$('interact').classList.toggle('near',!!near);$('interact').querySelector('span').textContent=near?near.kind==='portal'?'Перейти':near.kind==='camp'?'Відпочити':near.kind==='chest'?'Відкрити':'Взаємодія':'Взаємодія';$('interact').setAttribute('aria-label',near?'Взаємодія: '+near.name:'Взаємодія');$('status-hud').innerHTML=(h.effects||[]).map(e=>`<button data-open="effects" aria-label="${EFFECTS[e.id]?.name||e.id}: ${Math.ceil(e.left)} секунд" style="color:${EFFECTS[e.id]?.color||'#fff'}">${EFFECTS[e.id]?.icon||'?'}<small>${Math.ceil(e.left)}с ${e.stacks>1?'×'+e.stacks:''}</small></button>`).join('');let target=s.enemies.find(e=>e.id===h.target&&!e.dead);$('target-hud').hidden=!target;if(target){$('target-hud').innerHTML=`${target.boss?'♛ ':target.elite?'✦ ':''}<b>${escape(target.name)} · ${target.level}</b><div><i style="width:${Math.max(0,target.hp/target.maxHp*100)}%"></i></div><small>${target.aggression==='passive'?'Мирний · захищається':'Агресивний'} · ${killXP(h.level,target.level,target.boss,target.type)} XP<br>${escape(target.role)}${target.elite?'<br>Елітний: '+ELITES[target.elite].desc:''}${target.dungeonLocked?'<br>Захищений: спершу три елітні вартові':''}</small>`;}$('cast-hud').hidden=!h.cast;if(h.cast){$('cast-label').textContent=(h.cast.skill||skillFor(h,h.cast.skillId)||c.skills[h.cast.index]).name;$('cast-fill').style.width=(1-h.cast.left/h.cast.total)*100+'%';}$('death-hud').hidden=!h.dead;if(h.dead){$('death-reason').textContent=h.deathReason||'Загинув у бою';if($('modal').open)close();}$('vote-hud').hidden=!s.vote;if(s.vote){$('vote-title').textContent=s.vote.label;let yes=Object.values(s.vote.ballots).filter(v=>v==='yes').length,no=Object.values(s.vote.ballots).filter(v=>v==='no').length;$('vote-count').textContent=`За ${yes} · проти ${no} · ще ${Math.max(0,Math.ceil(s.vote.expires-s.clock))} с. При рівності вирішує лідер.`;$('vote-yes').disabled=!!s.vote.ballots[id];$('vote-no').disabled=!!s.vote.ballots[id];}if(session.error){toast(session.error);session.error=null;}}
function event(ev){if(!session)return;if(ev.time>=session.state.clock-1)feedback.play(ev,session.id);if(ev.type==='dungeonReward'&&ev.actor===session.id)open('rewards');if(ev.actor&&ev.actor!==session.id&&['loot','rest','death'].includes(ev.type))return;if(ev.text){logs.unshift(ev.text);logs=logs.slice(0,4);$('event-log').innerHTML=logs.map(t=>`<p>${escape(t)}</p>`).join('');if(['telegraph','story','ending','level'].includes(ev.type))toast(ev.text);if(ev.type==='ending')open('quest');}}
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.navigationMode){command('navigationMode',{mode:d.navigationMode})}if(d.feedback){feedback.set(d.feedback,!feedback.prefs[d.feedback]);refreshPanel()}if(d.storageMove){command('storageMove',{id:d.storageMove,direction:d.direction,count:Number(d.count)});refreshPanel()}if(d.storageMaterials){command('storageMaterials');refreshPanel()}if(d.sortInventory){command('inventorySort');refreshPanel()}if(d.dungeonChoice){command('dungeonChoice',{id:d.dungeonChoice,choice:d.choice});refreshPanel()}if(d.journeyChoice){let r=command('journeyChoice',{id:d.journeyChoice,choice:d.choice});if(!r?.error&&d.choice==='fight')close();else refreshPanel()}if(d.questTrack){command('questTrack',{id:d.questTrack});refreshPanel()}if(d.skillAugment){command('skillAugment',{id:d.skillAugment,choice:d.choice});refreshPanel()}if(d.forge){command('forge',{id:d.forge});refreshPanel()}if(d.salvage){command('salvage',{id:d.salvage});refreshPanel()}if(d.unequip){command('unequip',{id:d.unequip});refreshPanel()}if(d.dungeonStart){let r=command('dungeonStart',{route:d.dungeonStart==='risky'?'risky':'safe'});if(!r?.error)close()}if(d.inventoryTab){inventoryTab=d.inventoryTab;open('inventory');return}if(d.dialogue!==undefined){showDialogue(dialogueObject,DIALOGUES[dialogueObject.id][+d.dialogue].answer);return}if(d.recommend){command('recommendStats');refreshPanel()}if(d.buyEchoes){command('buyEchoes',{count:Number(d.buyEchoes)});refreshPanel()}if(d.skillTune){command('skillTune',{id:d.skillTune,key:d.tuneKey});refreshPanel()}if(d.skillUpgrade){command('skillUpgrade',{id:d.skillUpgrade});refreshPanel()}if(d.skillAssign){command('skillAssign',{id:d.skillAssign,slot:+d.slot});refreshPanel()}if(d.questAccept){command('questAccept',{id:d.questAccept});refreshPanel()}if(d.questClaim){command('questClaim',{id:d.questClaim});refreshPanel()}if(d.class){selectedClass=d.class;let name=$('character-name')?.value;sessionStorage.setItem('vyriy-name',name||'Мандрівник');choose();return;}if(d.close!==undefined){close();return;}if(d.open){open(d.open);return;}if(d.stat){command('stat',{stat:d.stat});refreshPanel()}if(d.spec){command('spec',{level:+d.spec,index:+d.index});refreshPanel()}if(d.equip){command('equip',{id:d.equip});refreshPanel()}if(d.use){command('use',{id:d.use});refreshPanel()}if(d.socket){command('socket',{card:d.socket});refreshPanel()}if(d.buy){command('buy',{template:d.buy});refreshPanel()}if(d.sell){command('sell',{id:d.sell,count:Number(d.sellCount||1)});refreshPanel()}if(d.offer){let others=Object.values(session.state.players).filter(p=>p.id!==session.id&&p.online&&Math.hypot(p.x-hero().x,p.y-hero().y)<4);panel='trade';show('Передати предмет',`<p class="notice">Одержувач має прийняти пропозицію протягом 30 с. Предмет зберігає свій ID та отримує нового власника один раз.</p>${others.map(p=>`<button class="btn" data-transfer="${escape(d.offer)}" data-to="${escape(p.id)}">${escape(p.name)}</button>`).join('')||'<p>Немає союзників поруч.</p>'}`)}if(d.transfer){command('offer',{item:d.transfer,to:d.to});open('coop')}if(d.accept){command('offerAccept',{id:d.accept});refreshPanel()}switch(b.id){case'quest-drawer-toggle':setQuestDrawer(!drawerOpen);break;case'modal-close':if(panel!=='create')close();break;case'start-local':startLocal();break;case'continue-local':startLocal(true);break;case'start-coop-menu':showCoop();break;case'back-local':session?close():choose();break;case'connect-server':{let base=$('server-url').value.trim(),room=$('room-code').value.trim(),name=$('coop-name').value.trim(),classId=$('coop-class').value;try{let u=new URL(base);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('Потрібна HTTP(S)-адреса сервера');b.disabled=true;let next=await RemoteSession.join(base,room,classId,name);session?.save();session?.close();session=next;close();toast('Кімнату створено. Код: '+session.room);}catch(err){b.disabled=false;toast(err.message)}break;}case'hero-open':open('hero');break;case'inventory-open':open('inventory');break;case'spec-open':open('spec');break;case'world-map':open('map');break;case'coop-open':open('coop');break;case'menu-open':open('menu');break;case'help-open':open('help');break;case'quest-open':open('quest');break;case'attack':case'skill0':case'skill1':case'potion':case'interact':action(b.id);break;case'respawn':command('respawn');break;case'vote-yes':command('vote',{value:'yes'});break;case'vote-no':command('vote',{value:'no'});break;case'ready-toggle':command('ready',{value:!hero().ready});refreshPanel();break;case'character-menu':session.save();if(session.mode==='online')session.close();choose();break;case'export-save':{let url=URL.createObjectURL(new Blob([JSON.stringify(session.state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='vyriy-save-v3.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);break;}}});
$('modal-body').addEventListener('change',async e=>{if(e.target.id==='import-save'){try{let saved=validateImported(JSON.parse(await e.target.files[0].text()));session?.close();session=new LocalSession(saved);session.save();close();toast('Збереження v3 відновлено')}catch(err){toast('Не вдалося імпортувати: '+err.message)}}});$('modal').addEventListener('cancel',e=>{if(panel==='create')e.preventDefault();else panel=null});$('modal').addEventListener('close',()=>{if(panel!=='create')panel=null});
let joyPointer=null;$('joystick').addEventListener('pointerdown',e=>{joyPointer=e.pointerId;$('joystick').setPointerCapture(e.pointerId);updateJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(joyPointer===e.pointerId)updateJoy(e)});function updateJoy(e){let r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.max(1,Math.hypot(dx,dy)/28);joystick={x:dx/len/28,y:dy/len/28};$('joy-knob').style.transform=`translate(${dx/len}px,${dy/len}px)`}for(let type of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(type,()=>{joystick={x:0,y:0};joyPointer=null;$('joy-knob').style.transform='';});
setInterval(()=>{if(session?.mode==='local'&&!document.hidden){$('save-status').textContent=session.save()?'Збережено · тільки на цьому пристрої':'Збереження недоступне — експортуйте прогрес';}},5000);window.addEventListener('pagehide',()=>session?.save());document.addEventListener('visibilitychange',()=>{if(document.hidden&&session?.mode==='local')session.save()});
async function boot(){sceneHandle=launchScene($('scene'),()=>session,{command,toast,interact,action,event,updateHUD,feedback:()=>feedback.prefs,joystick:()=>joystick});try{let r=await fetch('/api/health',{signal:AbortSignal.timeout(1500)});serverAvailable=r.ok&&(await r.json()).maxPlayers===8}catch{}try{session=await RemoteSession.resume()}catch{}if(session){toast('Мережеву сесію відновлено');return;}choose();}boot().then(()=>window.dispatchEvent(new Event('vyriy-ui-ready'))).catch(error=>window.dispatchEvent(new CustomEvent('vyriy-startup-error',{detail:error.message})));
